1	/**
2	 * The single source of truth for all pricing & accounting (CLAUDE.md rule 3).
3	 * Pure functions only — no DB, no side effects. Money is ALWAYS integer cents;
4	 * never use floats to represent money. The commission rate comes from config
5	 * (PLATFORM_COMMISSION_RATE), never a literal.
6	 *
7	 * No pricing math may live anywhere else in the codebase.
8	 */
9	
10	export type BlockMinutes = 15 | 30 | 45;
11	
12	/** Minimal provider shape needed to price a block. */
13	export interface BlockPricing {
14	  price_block_15_cents: number;
15	  price_block_30_cents: number;
16	  price_block_45_cents: number;
17	}
18	
19	const DEFAULT_COMMISSION_RATE = 0.05;
20	
21	/** Platform commission rate from config, clamped to [0, 1]; 0.05 fallback. */
22	export function getCommissionRate(): number {
23	  const raw = Number(process.env.PLATFORM_COMMISSION_RATE ?? DEFAULT_COMMISSION_RATE);
24	  if (!Number.isFinite(raw) || raw < 0 || raw > 1) return DEFAULT_COMMISSION_RATE;
25	  return raw;
26	}
27	
28	/** Round to the nearest cent, half-up. Inputs are non-negative money amounts. */
29	export function roundHalfUp(value: number): number {
30	  return Math.floor(value + 0.5);
31	}
32	
33	/** The block price (cents) a customer authorises at booking time. */
34	export function priceForBlock(
35	  provider: BlockPricing,
36	  blockMinutes: BlockMinutes,
37	): number {
38	  switch (blockMinutes) {
39	    case 15:
40	      return provider.price_block_15_cents;
41	    case 30:
42	      return provider.price_block_30_cents;
43	    case 45:
44	      return provider.price_block_45_cents;
45	  }
46	}
47	
48	/** Whole minutes run past the block (rounded up); 0 within the block. */
49	export function overageMinutes(
50	  elapsedSeconds: number,
51	  blockMinutes: BlockMinutes,
52	): number {
53	  const overSeconds = elapsedSeconds - blockMinutes * 60;
54	  if (overSeconds <= 0) return 0;
55	  return Math.ceil(overSeconds / 60);
56	}
57	
58	export interface SessionAccountingInput {
59	  priceBlockCents: number;
60	  overagePerMinCents: number;
61	  elapsedSeconds: number;
62	  blockMinutes: BlockMinutes;
63	  /** Defaults to the configured platform rate. */
64	  commissionRate?: number;
65	}
66	
67	export interface SessionAccounting {
68	  overageMinutes: number;
69	  totalCents: number;
70	  commissionCents: number;
71	  providerEarningsCents: number;
72	}
73	
74	/**
75	 * Final accounting at session end: block + overage → total, commission (half-up)
76	 * from config, provider keeps the rest. Tips are added later (addTip) and are
77	 * NOT subject to commission.
78	 */
79	export function computeSessionAccounting({
80	  priceBlockCents,
81	  overagePerMinCents,
82	  elapsedSeconds,
83	  blockMinutes,
84	  commissionRate = getCommissionRate(),
85	}: SessionAccountingInput): SessionAccounting {
86	  const overage = overageMinutes(elapsedSeconds, blockMinutes);
87	  const totalCents = priceBlockCents + overage * overagePerMinCents;
88	  const commissionCents = roundHalfUp(totalCents * commissionRate);
89	  const providerEarningsCents = totalCents - commissionCents;
90	  return {
91	    overageMinutes: overage,
92	    totalCents,
93	    commissionCents,
94	    providerEarningsCents,
95	  };
96	}
97	
98	/** Add a tip to provider earnings. Tips carry no platform commission. */
99	export function addTip(providerEarningsCents: number, tipCents: number): number {
100	  return providerEarningsCents + Math.max(0, tipCents);
101	}
102	
103	export interface CancellationInput {
104	  priceBlockCents: number;
105	  /** ISO time of a scheduled session, if any. */
106	  scheduledAt?: string | null;
107	  /** "Now" in epoch ms (injected for testability). */
108	  nowMs: number;
109	}
110	
111	export interface CancellationOutcome {
112	  /** "release" fully releases the hold; "charge" captures the full block. */
113	  action: "release" | "charge";
114	  captureCents: number;
115	}
116	
117	const ONE_HOUR_MS = 60 * 60 * 1000;
118	
119	/**
120	 * Cancellation policy (SPEC §5): cancelling a scheduled session ≥1h before its
121	 * start fully releases the hold; otherwise the full block is charged. (Ending an
122	 * in-progress call early still charges the full block — handled naturally by
123	 * computeSessionAccounting, since elapsed < block yields zero overage.)
124	 */
125	export function cancellationOutcome({
126	  priceBlockCents,
127	  scheduledAt,
128	  nowMs,
129	}: CancellationInput): CancellationOutcome {
130	  if (scheduledAt) {
131	    const startMs = new Date(scheduledAt).getTime();
132	    if (Number.isFinite(startMs) && startMs - nowMs >= ONE_HOUR_MS) {
133	      return { action: "release", captureCents: 0 };
134	    }
135	  }
136	  return { action: "charge", captureCents: priceBlockCents };
137	}
